import React, { useState, useEffect, useCallback } from "react";
import { Sparkles, Trash2, Loader2, Save, RefreshCw } from "lucide-react";

const STORAGE_KEY = "reframe-entries-v1";

export default function ReframeJournal() {
  const [thought, setThought] = useState("");
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [booting, setBooting] = useState(true);

  // Load saved entries on mount (persistent storage survives across sessions)
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(STORAGE_KEY);
        if (res && res.value) setEntries(JSON.parse(res.value));
      } catch (e) {
        // key not found or storage unavailable — start empty
      } finally {
        setBooting(false);
      }
    })();
  }, []);

  const persist = useCallback(async (next) => {
    setEntries(next);
    try {
      await window.storage.set(STORAGE_KEY, JSON.stringify(next));
    } catch (e) {
      /* in-memory only if storage write fails */
    }
  }, []);

  const reframe = async () => {
    const t = thought.trim();
    if (!t || loading) return;
    setLoading(true);
    setError("");
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          messages: [
            {
              role: "user",
              content:
                "You are a warm, evidence-based CBT coach. The user shares a stressful or negative thought. " +
                "Respond in 2–3 sentences with a kinder, more balanced reframe — no preamble, no bullet points, just the reframe.\n\nThought: " +
                t,
            },
          ],
        }),
      });
      const data = await response.json();
      const text = data.content
        .filter((b) => b.type === "text")
        .map((b) => b.text)
        .join("\n")
        .trim();
      const entry = {
        id: Date.now(),
        thought: t,
        reframe: text || "(no response)",
        ts: new Date().toLocaleString(),
      };
      await persist([entry, ...entries]);
      setThought("");
    } catch (e) {
      setError("Couldn't reach Claude. Try again in a moment.");
    } finally {
      setLoading(false);
    }
  };

  const remove = async (id) => {
    await persist(entries.filter((e) => e.id !== id));
  };

  const clearAll = async () => {
    await persist([]);
  };

  return (
    <div className="min-h-screen bg-stone-50 text-stone-800 p-6">
      <div className="max-w-2xl mx-auto">
        <div className="flex items-center gap-2 mb-1">
          <Sparkles className="w-5 h-5 text-violet-600" />
          <h1 className="text-2xl font-semibold tracking-tight">Reframe Journal</h1>
        </div>
        <p className="text-sm text-stone-500 mb-6">
          Write a heavy thought. Claude offers a gentler way to hold it. Entries save automatically and persist between sessions.
        </p>

        <div className="bg-white rounded-2xl border border-stone-200 p-4 shadow-sm">
          <textarea
            value={thought}
            onChange={(e) => setThought(e.target.value)}
            placeholder="e.g. I shipped a bug to prod and now the whole team thinks I'm careless."
            rows={3}
            className="w-full resize-none outline-none text-stone-700 placeholder:text-stone-400 text-[15px] leading-relaxed"
          />
          <div className="flex items-center justify-between mt-3 pt-3 border-t border-stone-100">
            <span className="text-xs text-stone-400 flex items-center gap-1">
              <Save className="w-3.5 h-3.5" /> auto-saved
            </span>
            <button
              onClick={reframe}
              disabled={loading || !thought.trim()}
              className="inline-flex items-center gap-2 bg-violet-600 hover:bg-violet-700 disabled:bg-stone-300 text-white text-sm font-medium px-4 py-2 rounded-xl transition-colors"
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
              {loading ? "Reframing…" : "Reframe with Claude"}
            </button>
          </div>
        </div>

        {error && <p className="text-sm text-red-500 mt-3">{error}</p>}

        <div className="flex items-center justify-between mt-8 mb-3">
          <h2 className="text-sm font-medium text-stone-500 uppercase tracking-wide">
            History {entries.length > 0 && `(${entries.length})`}
          </h2>
          {entries.length > 0 && (
            <button
              onClick={clearAll}
              className="inline-flex items-center gap-1 text-xs text-stone-400 hover:text-red-500 transition-colors"
            >
              <RefreshCw className="w-3.5 h-3.5" /> clear all
            </button>
          )}
        </div>

        {booting ? (
          <p className="text-sm text-stone-400">Loading saved entries…</p>
        ) : entries.length === 0 ? (
          <p className="text-sm text-stone-400">Nothing yet. Your reframes will collect here.</p>
        ) : (
          <div className="space-y-3">
            {entries.map((e) => (
              <div key={e.id} className="bg-white rounded-2xl border border-stone-200 p-4 shadow-sm">
                <div className="flex justify-between items-start gap-3">
                  <p className="text-[13px] text-stone-400 italic flex-1">“{e.thought}”</p>
                  <button onClick={() => remove(e.id)} className="text-stone-300 hover:text-red-500 transition-colors shrink-0">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
                <p className="text-[15px] text-stone-700 leading-relaxed mt-2">{e.reframe}</p>
                <p className="text-[11px] text-stone-400 mt-3">{e.ts}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

