s.addShape(p.ShapeType.ellipse,{x:11.4,y:4.6,w:1.4,h:1.4,fill:{color:AMBER,transparency:80},line:{type:"none"}});
s.addText("BEYOND THE CHAT BOX",{x:0.9,y:2.4,w:10,h:1.2,fontFace:HF,fontSize:46,bold:true,color:INK});
s.addText("Every surface Claude can render — inline, as files, and in the sandbox.",{x:0.92,y:3.7,w:9,h:0.6,fontFace:BF,fontSize:18,color:TEAL});
s.addText("A capabilities tour",{x:0.92,y:6.5,w:6,h:0.4,fontFace:BF,fontSize:12,color:MUT,italic:true});

// Slide 2 — three places
s = p.addSlide(); s.background={color:"FFFFFF"};
s.addText("Three places output lives",{x:0.7,y:0.5,w:12,h:0.8,fontFace:HF,fontSize:34,bold:true,color:"1A2230"});
const cols = [
  {x:0.7, c:TEAL, t:"Inline", d:"Charts, diagrams, interactive widgets, mockups, art, and live tool cards — rendered right in the conversation."},
  {x:5.05, c:VIOLET, t:"Files", d:"Markdown, HTML, React, SVG, Mermaid, PDF, Word, Excel, PowerPoint — open in the side panel, downloadable."},
  {x:9.4, c:AMBER, t:"Sandbox", d:"React & HTML apps that call the Claude API themselves and keep state across sessions."},
];
cols.forEach(col=>{
  s.addShape(p.ShapeType.roundRect,{x:col.x,y:1.7,w:3.4,h:4.6,rectRadius:0.12,fill:{color:"F4F6F9"},line:{color:"E3E8EE",width:1}});
  s.addShape(p.ShapeType.ellipse,{x:col.x+0.3,y:2.0,w:0.7,h:0.7,fill:{color:col.c},line:{type:"none"}});
  s.addText(col.t,{x:col.x+0.3,y:2.95,w:2.8,h:0.5,fontFace:HF,fontSize:22,bold:true,color:"1A2230"});
  s.addText(col.d,{x:col.x+0.3,y:3.5,w:2.85,h:2.5,fontFace:BF,fontSize:14,color:"55606E",lineSpacingMultiple:1.15,valign:"top"});
});

// Slide 3 — stats + chart
s = p.addSlide(); s.background={color:BG};
s.addText("By the numbers",{x:0.7,y:0.5,w:12,h:0.8,fontFace:HF,fontSize:34,bold:true,color:INK});
const stats=[
  {x:0.7,n:"9",l:"downloadable file formats",c:TEAL},
  {x:4.9,n:"12+",l:"inline widget types",c:AMBER},
  {x:9.1,n:"2",l:"sandbox superpowers",c:CORAL},
];
stats.forEach(st=>{
  s.addText(st.n,{x:st.x,y:1.7,w:3.5,h:1.3,fontFace:HF,fontSize:72,bold:true,color:st.c});
  s.addText(st.l,{x:st.x+0.05,y:3.0,w:3.5,h:0.6,fontFace:BF,fontSize:15,color:MUT});
});
s.addChart(p.ChartType.bar,[
  {name:"surfaces",labels:["Inline","Files","Sandbox"],values:[12,9,2]}
],{x:0.7,y:4.0,w:11.9,h:3.0,barDir:"col",chartColors:[TEAL,VIOLET,AMBER],
  showLegend:false,showValue:true,dataLabelColor:INK,dataLabelFontSize:14,
  catAxisLabelColor:MUT,valAxisHidden:true,catAxisLabelFontSize:14,
  barGapWidthPct:60,fill:{color:BG}});

p.writeFile({fileName:"/mnt/user-data/outputs/output-surfaces-deck.pptx"}).then(()=>console.log("saved"));
EOF
